import { randomBytes } from 'node:crypto';
import type { Readable } from 'node:stream';

/**
 * Where media files live. The database holds every file's metadata and an opaque storage key;
 * a storage adapter turns that key into bytes. Only the local-disk adapter exists today. A
 * cloud adapter (S3, R2, GCS) implements the same interface; see docs/architecture.md,
 * "Media storage".
 *
 * Keys are generated by the server only (`createStorageKey`) and never contain anything the
 * client sent: no file name, no path.
 */
export interface MediaStorage {
  readonly driver: string;
  /** Stores the file at `sourcePath` (a temporary upload) under `key`. Never overwrites. */
  put(key: string, sourcePath: string, options: { contentType: string }): Promise<void>;
  /** Null when no file is stored under the key. `range` is inclusive, in bytes. */
  open(key: string, range?: { start: number; end: number }): Promise<Readable | null>;
  /** Null when no file is stored under the key. */
  size(key: string): Promise<number | null>;
  /** Removes the file. Succeeds when it is already gone. */
  delete(key: string): Promise<void>;
}

export const STORAGE_KEY_PATTERN = /^[a-f0-9]{24}\/[a-f0-9]{32}\.(jpg|png|webp|gif|mp4|webm)$/;

export class InvalidStorageKeyError extends Error {
  constructor() {
    super('Invalid storage key');
    this.name = 'InvalidStorageKeyError';
  }
}

/** `<workspaceId>/<32 random hex characters>.<extension>`, for example `6650…/9f3a….jpg`. */
export function createStorageKey(workspaceId: string, extension: string): string {
  const key = `${workspaceId.toLowerCase()}/${randomBytes(16).toString('hex')}.${extension}`;
  assertStorageKey(key);
  return key;
}

export function assertStorageKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) throw new InvalidStorageKeyError();
}
